/**
 * "View sample" modal body — ports `sampleHtml()` from the design reference
 * (the original design reference, opened from the setup
 * screen's `su-sample` button). The design fabricates one record from its
 * in-memory `IND[cur].stream` mock; here it's a real record generated by
 * `POST /api/generate-sample` (`routes/industries.py::generate_sample`,
 * which runs the same `DataGenerator.tick()` the live producers use).
 */
import { useEffect, useState } from "react";
import type { PipelineMode } from "@/lib/industries-api";

export interface SampleModalContentProps {
  industryId: string;
  industryName: string;
  hz: number;
  mode: PipelineMode;
}

interface SampleRecord {
  sensor_name: string;
  value: number;
  unit: string;
  sensor_type: string;
  timestamp: string;
  fault_active: boolean;
}

function getErrorMessage(error: unknown): string {
  return error instanceof Error ? error.message : "Failed to generate a sample";
}

export function SampleModalContent({
  industryId,
  industryName,
  hz,
  mode,
}: SampleModalContentProps) {
  const [records, setRecords] = useState<SampleRecord[] | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    setRecords(null);
    setError(null);
    fetch("/api/generate-sample", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      credentials: "include",
      body: JSON.stringify({ industry: industryId, ticks: 1, update_rate_hz: hz }),
    })
      .then((res) => (res.ok ? res.json() : Promise.reject(new Error(`Request failed: ${res.status}`))))
      .then((data: { records?: SampleRecord[] }) => {
        if (!cancelled) setRecords(data.records ?? []);
      })
      .catch((err: unknown) => {
        if (!cancelled) setError(getErrorMessage(err));
      });
    return () => {
      cancelled = true;
    };
  }, [industryId, hz]);

  return (
    <>
      <div className="af-desc">
        Records the simulator emits at <b>{hz.toLocaleString()} rec/s</b>
        {mode === "zerobus" ? (
          <> and writes directly to the {industryName} Delta target.</>
        ) : (
          <>
            , published to <code>iot.{industryId}.{mode}</code> and mapped to the{" "}
            {industryName} schema.
          </>
        )}
      </div>
      {error && <p className="lede">Couldn&apos;t generate a sample: {error}</p>}
      {!error && !records && <p className="lede">Generating a sample record…</p>}
      {records && <pre className="samp">{JSON.stringify(records, null, 2)}</pre>}
    </>
  );
}
